/**
 * frontend/src/components/CameraRecognition.jsx
 * Version Professionnelle - Design épuré
 */

import React, { useState, useRef, useEffect, useCallback } from 'react';
import axios from 'axios';

const CAPTURE_INTERVAL_DEFAULT = 1500;
const CAPTURE_INTERVAL_FAST = 600;
const CONFIDENCE_THRESHOLD = 0.5;

const COLORS = {
  primary: '#2563EB',    // Bleu principal
  success: '#16A34A',    // Vert succès
  danger: '#DC2626',     // Rouge erreur
  gray: '#64748B',
  lightGray: '#F1F5F9',
  border: '#E2E8F0',
  background: '#FFFFFF',
  text: '#0F172A',
  muted: '#64748B',
};

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const overlayCanvasRef = useRef(null);
  const streamRef = useRef(null);
  const timeoutRef = useRef(null);

  const [cameraActive, setCameraActive] = useState(false);
  const [autoMode, setAutoMode] = useState(false);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState('idle'); // idle, scanning, success, warning, error

  const [capturedImage, setCapturedImage] = useState(null);
  const [registeredPhotoUrl, setRegisteredPhotoUrl] = useState(null);
  const [lastResult, setLastResult] = useState(null);
  const [faceBox, setFaceBox] = useState(null);

  const [successCount, setSuccessCount] = useState(0);
  const [errorCount, setErrorCount] = useState(0);
  const [frameCount, setFrameCount] = useState(0);
  const [lastDetectionTime, setLastDetectionTime] = useState(null);
  const [errorMsg, setErrorMsg] = useState(null);

  // ====================== AUDIO FEEDBACK ======================
  const playSound = useCallback((type) => {
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const oscillator = ctx.createOscillator();
      const gain = ctx.createGain();

      if (type === 'success') {
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(800, ctx.currentTime);
        setTimeout(() => oscillator.frequency.setValueAtTime(1200, ctx.currentTime + 0.1), 80);
        gain.gain.value = 0.25;
      } else {
        oscillator.type = 'sawtooth';
        oscillator.frequency.setValueAtTime(450, ctx.currentTime);
        gain.gain.value = 0.2;
      }

      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 1800;

      oscillator.connect(filter).connect(gain).connect(ctx.destination);
      oscillator.start();

      setTimeout(() => {
        gain.gain.linearRampToValueAtTime(0.001, ctx.currentTime + 0.35);
        oscillator.stop(ctx.currentTime + 0.45);
      }, type === 'success' ? 300 : 200);
    } catch (e) {
      // Audio non critique
    }
  }, []);

  // ====================== DÉMARRAGE CAMÉRA ======================
  const startCamera = async () => {
    try {
      setErrorMsg(null);
      setLoading(true);

      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "user" },
        audio: false,
      });

      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;

        videoRef.current.onloadedmetadata = async () => {
          setCameraActive(true);
          setLoading(false);
          await videoRef.current.play().catch(() => {});
          setAutoMode(true);
          if (addNotification) addNotification('Caméra démarrée avec succès', 'success');
        };
      }
    } catch (err) {
      const message = err.name === 'NotAllowedError' 
        ? 'Accès à la caméra refusé' 
        : 'Impossible d\'accéder à la caméra';

      setErrorMsg(message);
      setLoading(false);
      if (addNotification) addNotification(message, 'error');
    }
  };

  // ====================== ARRÊT TOTAL ======================
  const stopAll = () => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    if (videoRef.current) videoRef.current.srcObject = null;

    setCameraActive(false);
    setAutoMode(false);
    setStatus('idle');
    setFaceBox(null);
    setErrorMsg(null);
  };

  // ====================== BOUCLE CAPTURE ADAPTATIVE ======================
  const startCaptureLoop = useCallback(() => {
    if (!autoMode || !cameraActive) return;

    const captureFrame = async () => {
      if (!videoRef.current) return;

      try {
        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth || 1280;
        canvas.height = videoRef.current.videoHeight || 720;

        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.82);

        setFrameCount(prev => prev + 1);

        const response = await axios.post('/api/recognize/', {
          image: imageBase64.split(',')[1],
        });

        const data = response.data;
        const confidence = data.confidence || 0;

        if (data.face_box) setFaceBox(data.face_box);

        if (data.success && data.student) {
          setCapturedImage(imageBase64);
          setRegisteredPhotoUrl(data.registered_photo_url || null);
          setLastDetectionTime(new Date().toLocaleTimeString());
          setLastResult(data);
          setStatus('success');
          setSuccessCount(prev => prev + 1);
          playSound('success');
          addNotification(`${data.student} a été marqué présent`, 'success');

          setAutoMode(false);
          setTimeout(() => setAutoMode(true), 4500);
        } 
        else if (confidence >= CONFIDENCE_THRESHOLD) {
          setCapturedImage(imageBase64);
          setRegisteredPhotoUrl(data.registered_photo_url || null);
          setStatus('warning');
          setErrorMsg(`Visage détecté avec une confiance faible (${(confidence * 100).toFixed(1)}%)`);
          setErrorCount(prev => prev + 1);
          playSound('warning');

          if (timeoutRef.current) clearTimeout(timeoutRef.current);
          timeoutRef.current = setTimeout(captureFrame, CAPTURE_INTERVAL_FAST);
          return;
        } 
        else {
          setCapturedImage(imageBase64);
          setStatus('error');
          setErrorMsg('Visage non reconnu');
          setErrorCount(prev => prev + 1);
        }
      } catch (err) {
        setErrorMsg('Erreur de connexion avec le serveur');
        setStatus('error');
        setErrorCount(prev => prev + 1);
      }

      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      timeoutRef.current = setTimeout(captureFrame, CAPTURE_INTERVAL_DEFAULT);
    };

    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(captureFrame, 400);
  }, [autoMode, cameraActive, addNotification, playSound]);

  useEffect(() => {
    if (autoMode && cameraActive) {
      startCaptureLoop();
    }
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [autoMode, cameraActive, startCaptureLoop]);

  // ====================== CAPTURE MANUELLE ======================
  const handleManualCapture = async () => {
    if (!videoRef.current || loading) return;

    setLoading(true);
    setErrorMsg(null);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.85);
      setCapturedImage(imageBase64);

      const response = await axios.post('/api/recognize/', {
        image: imageBase64.split(',')[1],
      });

      const data = response.data;
      const confidence = data.confidence || 0;

      if (data.success && data.student) {
        setLastResult(data);
        setRegisteredPhotoUrl(data.registered_photo_url);
        setLastDetectionTime(new Date().toLocaleTimeString());
        setStatus('success');
        setSuccessCount(prev => prev + 1);
        playSound('success');
        addNotification(`${data.student} a été marqué présent`, 'success');
      } else if (confidence >= CONFIDENCE_THRESHOLD) {
        setStatus('warning');
        setErrorMsg(`Visage détecté avec une confiance faible (${(confidence * 100).toFixed(1)}%)`);
        setErrorCount(prev => prev + 1);
      } else {
        setStatus('error');
        setErrorMsg('Visage non reconnu');
        setErrorCount(prev => prev + 1);
      }
    } catch (err) {
      setErrorMsg('Erreur lors de la reconnaissance');
      setStatus('error');
      setErrorCount(prev => prev + 1);
    } finally {
      setLoading(false);
    }
  };

  // Placeholder pour photo enregistrée
  const RegisteredPhoto = () => (
    registeredPhotoUrl ? (
      <img src={registeredPhotoUrl} alt="Photo enregistrée" style={styles.photo} />
    ) : (
      <div style={styles.placeholder}>
        <div style={styles.silhouette}>Personne</div>
        <p style={styles.placeholderText}>Photo de référence</p>
      </div>
    )
  );

  // Nettoyage
  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    };
  }, []);

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1 style={styles.title}>Reconnaissance Faciale</h1>
        <p style={styles.subtitle}>Système de présence automatisé</p>
      </div>

      <div style={styles.videoContainer}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={styles.video}
          aria-label="Flux vidéo en direct"
        />
        <canvas ref={overlayCanvasRef} style={styles.overlay} />

        {cameraActive && (
          <div style={{
            ...styles.statusBadge,
            backgroundColor: status === 'success' ? COLORS.success :
                            status === 'warning' ? COLORS.warning :
                            status === 'error' ? COLORS.danger : COLORS.primary
          }}>
            {status === 'success' ? 'Reconnu' :
             status === 'warning' ? 'Confiance faible' :
             status === 'error' ? 'Non reconnu' : 'Analyse en cours'}
          </div>
        )}
      </div>

      <div style={styles.controls}>
        {!cameraActive ? (
          <button onClick={startCamera} disabled={loading} style={styles.btnPrimary}>
            {loading ? 'Démarrage...' : 'Démarrer la caméra'}
          </button>
        ) : (
          <>
            <button onClick={handleManualCapture} disabled={loading} style={styles.btnPrimary}>
              {loading ? 'Traitement...' : 'Capturer maintenant'}
            </button>

            <button
              onClick={() => setAutoMode(!autoMode)}
              style={{
                ...styles.btn,
                backgroundColor: autoMode ? COLORS.danger : COLORS.success
              }}
            >
              {autoMode ? 'Arrêter le scan automatique' : 'Démarrer le scan automatique'}
            </button>

            <button onClick={stopAll} style={styles.btnDanger}>
              Fermer la caméra
            </button>
          </>
        )}
      </div>

      {/* Comparaison des photos */}
      {capturedImage && (
        <div style={styles.comparisonSection}>
          <div style={styles.photoGrid}>
            <div>
              <h3 style={styles.sectionTitle}>Photo Capturée</h3>
              <img src={capturedImage} alt="Capture" style={styles.photo} />
            </div>
            <div>
              <h3 style={styles.sectionTitle}>Photo de Référence</h3>
              <RegisteredPhoto />
            </div>
          </div>
        </div>
      )}

      {/* Résultat */}
      {lastResult && status === 'success' && (
        <div style={styles.resultCard}>
          <h2 style={styles.successTitle}>Présence enregistrée</h2>
          <div style={styles.resultGrid}>
            <p><strong>Nom :</strong> {lastResult.student}</p>
            <p><strong>Email :</strong> {lastResult.email || 'Non renseigné'}</p>
            <p><strong>Confiance :</strong> {(lastResult.confidence * 100).toFixed(1)}%</p>
            <p><strong>ID Présence :</strong> {lastResult.attendance_id}</p>
            <p><strong>Heure :</strong> {lastDetectionTime}</p>
          </div>
        </div>
      )}

      {errorMsg && (
        <div style={status === 'warning' ? styles.warningCard : styles.errorCard}>
          {errorMsg}
        </div>
      )}

      {/* Statistiques */}
      <div style={styles.statsSection}>
        <h3 style={styles.sectionTitle}>Statistiques</h3>
        <div style={styles.statsGrid}>
          <div>Succès : <strong style={{ color: COLORS.success }}>{successCount}</strong></div>
          <div>Échecs : <strong style={{ color: COLORS.danger }}>{errorCount}</strong></div>
          <div>Frames traités : <strong>{frameCount}</strong></div>
          <div>Dernière détection : <strong>{lastDetectionTime || '—'}</strong></div>
        </div>
      </div>

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(8px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

const styles = {
  container: {
    padding: '40px 20px',
    maxWidth: '1200px',
    margin: '0 auto',
    backgroundColor: COLORS.background,
    fontFamily: 'system-ui, -apple-system, Arial, sans-serif',
  },
  header: {
    textAlign: 'center',
    marginBottom: '32px',
  },
  title: {
    fontSize: '2.1rem',
    fontWeight: '700',
    color: COLORS.text,
    margin: '0 0 8px 0',
  },
  subtitle: {
    color: COLORS.muted,
    fontSize: '1.05rem',
  },

  videoContainer: {
    position: 'relative',
    borderRadius: '12px',
    overflow: 'hidden',
    boxShadow: '0 10px 30px rgba(0, 0, 0, 0.12)',
    backgroundColor: '#000',
    marginBottom: '28px',
  },
  video: {
    width: '100%',
    display: 'block',
  },
  overlay: {
    position: 'absolute',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    pointerEvents: 'none',
  },
  statusBadge: {
    position: 'absolute',
    top: '20px',
    right: '20px',
    color: 'white',
    padding: '8px 18px',
    borderRadius: '30px',
    fontSize: '0.92rem',
    fontWeight: '600',
  },

  controls: {
    display: 'flex',
    gap: '14px',
    flexWrap: 'wrap',
    marginBottom: '32px',
  },
  btn: {
    flex: 1,
    padding: '16px 20px',
    border: 'none',
    borderRadius: '8px',
    fontWeight: '600',
    fontSize: '1rem',
    cursor: 'pointer',
    transition: 'all 0.2s',
  },
  btnPrimary: {
    backgroundColor: COLORS.primary,
    color: 'white',
  },
  btnDanger: {
    backgroundColor: COLORS.danger,
    color: 'white',
  },

  comparisonSection: {
    margin: '32px 0',
  },
  photoGrid: {
    display: 'grid',
    gridTemplateColumns: '1fr 1fr',
    gap: '24px',
  },
  sectionTitle: {
    fontSize: '1.1rem',
    fontWeight: '600',
    color: COLORS.text,
    marginBottom: '12px',
  },
  photo: {
    width: '100%',
    borderRadius: '10px',
    border: `2px solid ${COLORS.border}`,
  },
  placeholder: {
    width: '100%',
    height: '320px',
    backgroundColor: '#F8FAFC',
    border: `2px dashed ${COLORS.border}`,
    borderRadius: '10px',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    color: COLORS.muted,
  },
  silhouette: {
    fontSize: '4.5rem',
    marginBottom: '12px',
    opacity: 0.4,
  },
  placeholderText: {
    fontSize: '0.95rem',
  },

  resultCard: {
    backgroundColor: '#F0FDF4',
    borderLeft: `5px solid ${COLORS.success}`,
    padding: '24px',
    borderRadius: '10px',
    margin: '24px 0',
    animation: 'fadeIn 0.4s ease',
  },
  successTitle: {
    color: COLORS.success,
    margin: '0 0 16px 0',
    fontSize: '1.35rem',
  },
  resultGrid: {
    display: 'grid',
    gap: '10px',
    fontSize: '1.02rem',
  },

  warningCard: {
    backgroundColor: '#FEFCE8',
    borderLeft: `5px solid ${COLORS.warning}`,
    padding: '20px',
    borderRadius: '10px',
    margin: '20px 0',
  },
  errorCard: {
    backgroundColor: '#FEF2F2',
    borderLeft: `5px solid ${COLORS.danger}`,
    padding: '20px',
    borderRadius: '10px',
    margin: '20px 0',
    color: COLORS.danger,
  },

  statsSection: {
    marginTop: '40px',
  },
  statsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
    gap: '16px',
    fontSize: '1.05rem',
  },
};

export default CameraRecognition;
